    @Test void documentsTaskAndReceiptProblemResponses() throws Exception {
        var taskBody="{\"priority\":\"LOW\",\"completionCriterion\":\"Updated\",\"rowVersion\":1,\"requestId\":\"40000000-0000-0000-0000-000000000004\"}";
        org.mockito.Mockito.reset(service); when(service.updateTaskExecution(eq(project),eq(item),any(),eq(actor))).thenThrow(new ValidationFailure("completionCriterion","invalid"));
        mvc.perform(patch("/api/v1/projects/{projectId}/management/tasks/{itemId}",project,item).contentType("application/json").content(taskBody).with(csrf()).with(authentication(auth))).andExpect(status().isBadRequest()).andDo(document("project-management-task-error-400",resource(ResourceSnippetParameters.builder().responseFields(problemFields()).build())));
        org.mockito.Mockito.reset(service); when(service.updateTaskExecution(eq(project),eq(item),any(),eq(actor))).thenThrow(new org.springframework.security.access.AccessDeniedException("FORBIDDEN"));
        mvc.perform(patch("/api/v1/projects/{projectId}/management/tasks/{itemId}",project,item).contentType("application/json").content(taskBody).with(csrf()).with(authentication(auth))).andExpect(status().isForbidden()).andDo(document("project-management-task-error-403",resource(ResourceSnippetParameters.builder().responseFields(problemFields()).build())));
        org.mockito.Mockito.reset(service); when(service.updateTaskExecution(eq(project),eq(item),any(),eq(actor))).thenThrow(new NoSuchElementException("NOT_FOUND"));
        mvc.perform(patch("/api/v1/projects/{projectId}/management/tasks/{itemId}",project,item).contentType("application/json").content(taskBody).with(csrf()).with(authentication(auth))).andExpect(status().isNotFound()).andDo(document("project-management-task-error-404",resource(ResourceSnippetParameters.builder().responseFields(problemFields()).build())));
        org.mockito.Mockito.reset(service); when(service.updateTaskExecution(eq(project),eq(item),any(),eq(actor))).thenThrow(new IllegalStateException("PROJECT_MANAGEMENT_DISABLED"));
        mvc.perform(patch("/api/v1/projects/{projectId}/management/tasks/{itemId}",project,item).contentType("application/json").content(taskBody).with(csrf()).with(authentication(auth))).andExpect(status().isConflict()).andDo(document("project-management-task-error-409",resource(ResourceSnippetParameters.builder().responseFields(problemFields()).build())));
        org.mockito.Mockito.reset(service); when(service.receipt(project,request,actor)).thenThrow(new NoSuchElementException("NOT_FOUND"));
        mvc.perform(get("/api/v1/projects/{projectId}/management/requests/{requestId}",project,request).with(authentication(auth))).andExpect(status().isNotFound()).andDo(document("project-management-receipt-error-404",resource(ResourceSnippetParameters.builder().responseFields(problemFields()).build())));
    }
